return {
  [ [[v5748eaic9onf]] ] = { t = [[多武器、额外攻击与双持武器战斗]], q = [[如果我因为高BAB而拥有额外攻击，我能用不同的武器进行这些攻击而不承受双持武器战斗的减值吗？]], a = [=[可以。简单地说，只有当你想要每轮多得到一次额外攻击时，才会承受双持武器战斗的减值。

假设你是6级战士（BAB +6/+1），一只手持[[长剑]]，另一只手持[[轻型硬头锤]]。不使用双持武器战斗时，你可能的全力攻击组合有：

(A) 长剑+6，长剑+1

(B) 硬头锤+6，硬头锤+1

(C) 长剑+6，硬头锤+1

(D) 硬头锤+6，长剑+1

所有这些组合都让你正好发动两次攻击，一次+6、一次+1。你没有得到任何额外攻击，因此你并未使用双持武器战斗规则，也就不承受任何双持武器战斗减值。

若你拥有[[即时备战]]，你甚至可以在回合开始时只持用一件武器，用它发动你的主要攻击，在第一次攻击后以自由动作拔出第二件武器，再用第二件武器进行你的迭代攻击（“迭代攻击”是个非正式说法，指“因高BAB而获得的额外攻击”）。只要你正确使用BAB的数值来进行迭代攻击，并且攻击次数没有超过BAB每轮所赋予的次数，你就不被视为在使用双持武器战斗，因此也不承受任何双持武器战斗减值。

[[核心规则书]]中的双持武器战斗规则，专指因在副手持用第二件武器而获得一次额外攻击。在上面四个例子中并没有额外攻击，因此你不是在使用双持武器战斗。

仍以长剑／硬头锤为例，如果你使用双持武器战斗，你的选择实际上反而比不使用时更少。你的选项为（忽略主手／副手减值）：

(A') 主手长剑+6，主手长剑+1，副手硬头锤+6

(B') 主手硬头锤+6，主手硬头锤+1，副手长剑+6

换言之，一旦你决定在本回合使用双持武器战斗来获得那一次额外攻击（你必须在本回合发动任何攻击之前做出这个决定），你就被锁定在这样的格式中：“我的主手武器负责主要攻击和迭代攻击，我的副手武器只负责那一次额外攻击，并且我要承受双持武器战斗的减值。”]=], book = [[核心规则书]], date = [[2011/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9onf]], cat = [[FAQ]], ai = false, pages = { [[特殊攻击]] } },
  [ [[v5748eaic9qd4]] ] = { t = [[双持武器战斗与借机攻击]], q = [[如果我在自己的回合中使用双持武器战斗来攻击，那么在下个回合开始前进行的借机攻击，是否也要承受这一减值？]], a = [=[不会。减值在你完成允许你用两件武器攻击的那次全力攻击动作后立即结束。你进行的任何借机攻击都使用你的正常攻击加值。

一般而言，你在自己回合中进行攻击时承受的减值不会延续到借机攻击上，除非另有明文规定（比如[[猛力攻击]]或[[寓守于攻]]带来的减值）。

这个回答最初发表于2012年9月25日的Paizo博客。]=], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qd4]], cat = [[FAQ]], ai = false, pages = { [[特殊攻击]] } },
  [ [[v5748eaic9qie]] ] = { t = [[徒手打击与双持武器战斗]], q = [[我能使用双持武器战斗，在一轮内发动两次徒手打击吗？]], a = [[可以。]], book = [[核心规则书]], date = [[2013/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qie]], cat = [[FAQ]], ai = false, pages = { [[特殊攻击]] } },
  [ [[v5748eaic9qut]] ] = { t = [[异种武器与持用手数]], q = [[如果一件武器双手持用时可视为军用武器，而在拥有异种武器擅长时可以单手持用，那么我在没有异种武器擅长的情况下，能否承受-4减值单手持用它？]], a = [=[不能。

