（其他带有这种单手异种例外的武器，比如[[矮人重斧]]，同理。）

2013年7月26日修订：更正第二句中的一处笔误，原文误写成“你无法双手持用双手武器”。]=], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qut]], cat = [[FAQ]], ai = false, pages = { [[装备]], [[重剑]] } },
  [ [[v5748eaic9n9y]] ] = { t = [[物品视为法术]], q = [=[使用药水、卷轴、法杖或魔杖，是否算作“施展法术”，从而适用于[[增强召唤]]、[[法术专攻]]、塑能学派法师对塑能法术造成额外伤害的能力、血脉能力等专长与特殊能力？]=], a = [[不会。除非另有明文规定，修改你所施展法术的专长和能力，只作用于真正的施法，不作用于使用模拟施法或类似施法的魔法物品。]], book = [[核心规则书]], date = [[2010/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9n9y]], cat = [[FAQ]], ai = true, pages = { [[魔法物品]] } },
  [ [[v5748eaic9soj]] ] = { t = [[魔法物品、佩戴者与持续时间]], q = [[如果一件魔法物品给予佩戴者一个有持续时间的效果，我能否戴上它、激活效果、再把它脱下，并让效果继续存在？]], a = [[不能。一旦你脱下一件给予佩戴者效果的物品，你就不再是佩戴者，因此所有剩余的持续时间立即终止。如果该物品的效果作用于所有者、持用者等，情况也是一样。如果物品效果没有把受益者指明为佩戴者（或所有者、持用者等），那么除非另有说明，物品被取下后该效果仍然持续。]], book = [[核心规则书]], date = [[2014/01/12]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9soj]], cat = [[FAQ]], ai = true, pages = { [[魔法物品]] } },
  [ [[v5748eaic9tab]] ] = { t = [[光与黑暗]], q = [[我被光和黑暗搞糊涂了。谁来帮帮我！]], a = [[请看这篇关于光与黑暗的[https://paizo.com/community/blog/v5748dyo5lhfm 扩展FAQ]。]], book = [[核心规则书]], date = [[2015/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9tab]], cat = [[FAQ]], ai = true, pages = { [[视力和光源]] } },
  [ [[v5748eaic9vct]] ] = { t = [[昏暗光照]], q = [=[当某项能力要求角色处于阴影附近或昏暗区域中（比如[[影舞者]]的阴影跳跃或视线躲藏）时，它与昏暗视觉、黑暗视觉等能力如何互动？]=], a = [=[虽然游戏中大多数生物确实拥有昏暗视觉或黑暗视觉，但当规则谈到处于或临近某个客观的光照等级（例如“处于昏暗区域中”）时，指的始终是从常规视觉（比如人类的视觉）角度来看的光照与黑暗状态。例外是那些取决于观察者视角的效果，比如[[魂兽与魂域/苍天魂域|苍天魂域]]萨满的虚空缠身能力；这类效果会用文字明确指出，该能力改变的是（或取决于）那个生物的视角，而不是整体的光照等级。]=], book = [[核心规则书]], date = [[2017/01/01]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vct]], cat = [[FAQ]], ai = true, pages = { [[视力和光源]], [[影舞者]] } },
  [ [[v5748eaic9pyy]] ] = { t = [[要害打击与跳跃攻击、冲锋]], q = [=[我能把要害打击与[[跳跃攻击]]或冲锋同时使用吗？]=], a = [[不能。要害打击只能作为攻击动作的一部分使用，而攻击动作是标准动作的一种。跳跃攻击是一种特殊的整轮动作，其中包含一次近战攻击，而不是一个攻击动作。冲锋使用的措辞类似，同样不能与要害打击组合使用。]], book = [[核心规则书]], date = [[2012/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9pyy]], cat = [[FAQ]], ai = false, pages = { [[要害打击]] } },
  [ [[v5748eaic9ojt]] ] = { t = [[武器娴熟与战技]], q = [[如果我拥有武器娴熟，能否在战技检定中用敏捷加值代替力量加值？]], a = [=[这取决于你尝试的是哪种战技。卸武、击破和摔绊通常是仅有的几种真正用武器来执行的战技，因此武器的加值会作用于这次检定。所以，如果你尝试卸武、击破或摔绊战技，你可以在战技检定中以敏捷加值取代力量调整值（当然，前提是你用的是可娴熟使用的武器）。对于其他战技，则按决定CMB的常规规则（用力量而非敏捷）。

[[灵巧武艺]]专长适用于所有战技，而不仅限于卸武、击破和摔绊，所以对于使用战技的敏捷型生物，它仍然是个有用的选择。]=], book = [[核心规则书]], date = [[2011/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ojt]], cat = [[FAQ]], ai = false, pages = { [[武器娴熟]] } },
  [ [[v5748eaic9sk0]] ] = { t = [[长矛与临时武器]], q = [=[我能用[[长矛]]同时攻击10尺和5尺处的敌人吗？我知道触及武器的规则不允许它们攻击邻接的敌人，但我能否借用临时武器规则，说长矛的钝头一端类似木棒，用它来攻击邻接的敌人？我知道临时武器规则说它们适用于并非设计成武器的物体，但我的长矛的钝头一端并不是设计成武器的，对吧？]=], a = [=[你可以选择把长矛当作临时钝击武器来持用。这时它只威胁你邻接的方格，而不威胁更远的方格。不过，如果你是把它作为长矛持用、以威胁更远的方格，那么你的握持方式就排除了把它用作临时钝击武器。规则没有说明在这两种方式之间切换要花多长时间，但对于长剑这类单手武器，在单手与双手握持之间切换是一个自由动作（因此只能在你的回合中进行），所以切换至少应当花费同样长的时间，从而使你无法同时威胁所有这些方格。顺带一提，以这种方式把长矛当作临时武器使用时，你不能受益于它可能拥有的任何魔法强化，也不能加上仅在用长矛攻击时才适用的益处（比如[[武器专攻]]（长矛）），但你可以应用使用临时武器带来的任何益处（比如[[随手武器]]）。]=], book = [[核心规则书]], date = [[2014/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9sk0]], cat = [[FAQ]], ai = false, pages = { [[装备]], [[长矛]] } },
  [ [[v5748eaic9t3f]] ] = { t = [[体型变化与伤害骰成长]], q = [[当武器的体型或等效体型发生变化时，我对人造武器和天生武器伤害骰的增减感到困惑。有好几张不同的表，我不确定该用哪一张。]], a = [[当生物的武器或天生攻击所造成的伤害，因其体型（或其武器的体型）发生变化而改变时，使用以下规则来确定新的伤害。

* 如果体型增加一级，在表中查出原始伤害，并将伤害提高两级。如果原始体型为小型或更小（或被视为小型或更小），或者原始伤害为1d6或更低，则改为提高一级。

* 如果体型减小一级，在表中查出原始伤害，并将伤害降低两级。如果原始体型为中型或更小（或被视为中型或更小），或者原始伤害为1d8或更低，则改为降低一级。

* 如果表中找不到原始的伤害骰数量，则在调整伤害骰之前先应用以下处理。如果伤害是若干d6，则在表中找到次低的d6骰数，并把同样数量的d8作为原始伤害值（例如，10d6改视为8d8）。如果伤害是若干d8，则在表中找到次高的d8骰数，并把同样数量的d6作为原始伤害值（例如，5d8改视为6d6）。得到新的伤害值后，再按上述级数调整。

* 如果表中没有提到该骰型，则在调整伤害骰之前先应用以下规则。2d4在表中视为1d8，3d4视为2d6，更多的d4依此类推。1d12在表中视为2d6，更多的d12依此类推。

* 最后，无论初始体型如何，2d10提高为4d8、降低为2d8，更多的d10依此类推。

'''伤害骰成长表：'''1、1d2、1d3、1d4、1d6、1d8、1d10、2d6、2d8、3d6、3d8、4d6、4d8、6d6、6d8、8d6、8d8、12d6、12d8、16d6]], book = [[核心规则书]], date = [[2015/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9t3f]], cat = [[FAQ]], ai = false, pages = { [[装备]] } },
  [ [[v5748eaic9t5u]] ] = { t = [[体型增大与等效体型增大]], q = [[如果我同时拥有改变实际体型、等效体型和伤害骰的多种效果，伤害该如何计算？]], a = [=[按照体型变化的规则，体型变化不叠加，所以如果你有多个改变体型的效果（例如一个使你体型增加一级，另一个增加两级），只有最大的那个生效。等效体型增大（包括“造成伤害时如同比实际体型大一级”“你的伤害骰类型提高一级”及类似措辞）同样如此：它们彼此不叠加，只取最大的那个。不过，你可以同时各有一个，它们会共同起作用（例如，[[变巨术]]把你的实际体型增至大型，而[[猛击]]把你盾牌的等效体型提高两级，总计造成2d6伤害）。]=], book = [[核心规则书]], date = [[2015/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9t5u]], cat = [[FAQ]], ai = true, pages = { [[装备]] } },
  [ [[v5748eaic9uni]] ] = { t = [[触及增加与体型增大]], q = [=[大型或更大生物持用触及武器的说明里说，它们可以攻击至自然触及两倍远的目标，但不能攻击处于自然触及或更近处的目标。我应该在[[突刺]]或[[长臂咒]]这类改变触及的效果之前还是之后计算这个加倍？]=], a = [=[先把与你体型相符的基础触及加倍，然后再加入所有其他能力。例如，一个持用长矛、受到‘长臂咒’影响、并使用突刺专长的[[食人魔]]，可以攻击15、20、25或30尺外的生物，但无法攻击0、5或10尺外的生物。]=], book = [[核心规则书]], date = [[2016/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9uni]], cat = [[FAQ]], ai = true, pages = { [[装备]] } },
  [ [[v5748eaic9qdb]] ] = { t = [[武僧武器特性]], q = [[武僧会自动擅长所有具有“武僧”武器特性的武器吗？]], a = [[按文字所述，不会——“武僧”武器特性只是说明武僧可以在疾风连击中使用该武器，并不赋予对该武器的擅长。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qdb]], cat = [[FAQ]], ai = false, pages = { [[装备]], [[武僧]] } },
  [ [[v5748eaic9nvd]] ] = { t = [[摔绊武器]], q = [[如果想发动摔绊战技，必须使用具有摔绊特性的武器吗？]], a = [=[不必。发动摔绊战技时，你不必使用具有摔绊特性的武器——任何武器都行。例如，你可以用[[长剑]]或[[徒手打击]]来摔绊，尽管这些武器并不具有摔绊特性。

请注意，发动摔绊战技时使用具有摔绊特性的武器（又称“摔绊武器”）有一个好处：如果你的摔绊攻击失败10点或更多，你可以丢弃这件摔绊武器，来代替被击倒在地。

另外顺带一提，发动[[卸武]]战技时你也不必使用具有卸武特性的武器（又称“卸武武器”）——任何武器都行。

注：这是对这条FAQ的修订，依据是一篇Paizo博客中有关用武器发动战技的说明。此前的FAQ称，使用摔绊武器是把武器强化加值、武器专攻加值等类似加值应用到摔绊战技检定上的唯一方法。该博客中的澄清意味着，任何用于摔绊的武器在发动摔绊战技时都会应用这些加值，因此本FAQ已更新，删去了“只有摔绊武器才能应用这些加值”的限制。]=], book = [[核心规则书]], date = [[2011/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nvd]], cat = [[FAQ]], ai = false, pages = { [[装备]], [[摔绊]] } },
  [ [[v5748eaic9nef]] ] = { t = [[武器专精（射线、炸弹）]], q = [[我能选择“武器专精（射线）”或“精通重击（射线）”作为专长吗？“武器专精（炸弹）”或“精通重击（炸弹）”呢？]], a = [=[这四个都是有效的选择。

